#include SOURCE
#include <algorithm>
#include <array>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <utility>
#include <vector>
int main(int argc,char**argv){
 if(argc!=4)return 1;
 const int n=std::atoi(argv[1]),mode=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 std::mt19937 rng(61022);std::vector<std::pair<int,int>> edges;
 if(mode==0){for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)edges.emplace_back(i,i+step);}
 if(mode==1){for(int i=1;i<n;++i)edges.emplace_back(0,i);}
 if(mode>=2&&mode<=3){for(int i=0;i<n;++i)edges.emplace_back(0,n-1);}
 if(mode==4){for(int i=0;i<n;++i)edges.emplace_back(int(rng()%n),int(rng()%n));}
 if(mode>=5){for(int i=0;i<n;++i){int a=int(rng()%n);edges.emplace_back(a,a);}}
 RollbackUnionFind uf(n);uf.reserve_history(static_cast<std::size_t>(n)*2);
 if(mode>=2&&mode<=3)for(int i=1;i<n;++i)uf.unite(0,i);
 if(mode>=5)for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)uf.unite(i,i+step);
 const auto base=uf.get_state();std::uint64_t checksum=0;
 // 同じ操作列を一度流して容量・ページ確保を計時外へ出す。
 for(auto [a,b]:edges){if(mode==6)(void)uf.same(a,b);else{uf.unite(a,b);if(mode==3||mode==5)uf.undo();}}uf.rollback(base);
 const auto begin=std::chrono::steady_clock::now();
 for(int r=0;r<reps;++r){
  for(auto [a,b]:edges){if(mode==6)checksum+=uf.same(a,b);else{checksum+=uf.unite(a,b);if(mode==3||mode==5)uf.undo();}}
  if(mode==0){for(std::size_t i=0;i<edges.size();++i)uf.undo();}else uf.rollback(base);
  checksum+=static_cast<unsigned>(uf.get_state())+static_cast<unsigned>(uf.component_count());
 }
 const auto end=std::chrono::steady_clock::now();
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count();
 if(uf.get_state()!=base)return 2;
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(ns),static_cast<std::uintmax_t>(checksum));
}
